KG42.register("rules-59f1a77b3ea3a7a404d097e9",{"id":"32-wholesale_prosumer_storage::v141-c-R010","paper":"32-wholesale_prosumer_storage","record":{"rule_id":"v141-c-R010","mechanism_id":"v141-a-M01","name":"Market payment","process_stage":"settlement","market_meaning":"Electricity procurement from the grid incurs costs at dynamic real-time prices. Scope: Community grid-electricity procurement in the two-stage STEP model. Condition: Electricity is procured from the grid. Electricity fed into the day-ahead market receives compensation at the dynamic wholesale spot price. Scope: Community electricity infeed into the wholesale day-ahead market. Condition: Electricity is fed into the day-ahead market.","independence_rationale":"Relations governed by the approved function settlement.payment under the fixed relation-ownership template. Conditional branches retain their explicit scope in local constraints.","V":["execution.energy_trade","settlement.payment"],"E":[{"edge_id":"v141-c-R010-E001","source":"settlement.payment","target":"execution.energy_trade","type":"conditional_on","constraint_ids":["v141-c-R010-C001","v141-c-R010-C002"],"evidence_ids":["v141-b-g01-e09","v141-b-g02-e30"]}],"omega":{"market_type":"LEM_DEM","network_level":null,"jurisdiction":null,"pricing_scope":null,"time_scale":null,"participant_types":[],"trading_stage":"settlement","context_text":"Community electricity infeed into the wholesale day-ahead market. | Community grid-electricity procurement in the two-stage STEP model.","unknown_fields":["network_level","jurisdiction","pricing_scope","time_scale","participant_types"],"evidence_ids":["v141-b-g01-e09","v141-b-g02-e30"]},"x":[{"variable_id":"v141-c-R010-x001","symbol":"G_{DA}^{(t,h)}","meaning":"Day-ahead grid consumption of house h in time step t, i.e. the day-ahead procurement quantity from the grid.","kind":"operational","domain":"real-valued electricity quantity; bounds not specified in the supplied source","unit":null,"indices":["t","h"],"evidence_ids":["v141-b-g02-e21","v141-b-g02-e31"]},{"variable_id":"v141-c-R010-x002","symbol":"F_{DA}^{(t,h)}","meaning":"Day-ahead feed of house h in time step t, i.e. the quantity fed into the day-ahead market.","kind":"operational","domain":"real-valued electricity quantity; bounds not specified in the supplied source","unit":null,"indices":["t","h"],"evidence_ids":["v141-b-g02-e21","v141-b-g02-e31"]},{"variable_id":"v141-c-R010-x003","symbol":"G_{ID}^{(t,h,s)}","meaning":"Intraday grid consumption of house h in time step t and scenario s, i.e. the second-stage procurement quantity from the grid.","kind":"operational","domain":"real-valued electricity quantity; bounds not specified in the supplied source","unit":null,"indices":["t","h","s"],"evidence_ids":["v141-b-g02-e21","v141-b-g02-e32"]}],"theta":[{"parameter_id":"v141-c-R010-p001","symbol":"p_{G\\_DA}^{(t)}","meaning":"Dynamic day-ahead price of grid electricity in Eq. (15); Table 1 gives the related day-ahead grid-price notation p_{DA}^{(t)}.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":["t"],"evidence_ids":["v141-b-g02-e21","v141-b-g02-e30","v141-b-g02-e31"]},{"parameter_id":"v141-c-R010-p002","symbol":"p_{F}^{(t)}","meaning":"Dynamic compensation price for electricity fed into the grid/day-ahead market; the source also states that feed-in prices are set equal to the RPD wholesale spot prices.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":["t"],"evidence_ids":["v141-b-g02-e21","v141-b-g02-e31","v141-b-g01-e09","v141-b-g02-e36"]},{"parameter_id":"v141-c-R010-p003","symbol":"p_{G\\_ID}^{(t,s)}","meaning":"Uncertain intraday spot price of grid electricity in Eq. (16); Table 1 gives the related intraday grid-price notation p_{ID}^{(t,s)}.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":["t","s"],"evidence_ids":["v141-b-g02-e21","v141-b-g02-e32"]},{"parameter_id":"v141-c-R010-p004","symbol":"\\pi^{(s)}","meaning":"Probability of occurrence of scenario s in the expected intraday payment expression; Table 1 writes the related notation \\pi_s.","value":{"kind":"unspecified","number_value":null,"text_value":null},"unit":null,"indices":["s"],"evidence_ids":["v141-b-g02-e21","v141-b-g02-e32"]}],"phi":[{"constraint_id":"v141-c-R010-C001","kind":"mathematical","role":"core","statement":"Electricity procurement from the grid incurs costs at dynamic real-time prices. Scope: Community grid-electricity procurement in the two-stage STEP model. Condition: Electricity is procured from the grid.","expression":"\\sum_{h \\in H}\\sum_{t \\in T} p_{G\\_DA}^{(t)} G_{DA}^{(t,h)} + \\sum_{t \\in T}\\sum_{h \\in H}\\sum_{s \\in S} \\pi^{(s)} p_{G\\_ID}^{(t,s)} G_{ID}^{(t,h,s)}","formalization_origin":"source","template_id":null,"members":["settlement.payment","execution.energy_trade"],"variable_refs":["v141-c-R010-x001","v141-c-R010-x003"],"parameter_refs":["v141-c-R010-p001","v141-c-R010-p003","v141-c-R010-p004"],"evidence_ids":["v141-b-g02-e30","v141-b-g02-e31","v141-b-g02-e32"]},{"constraint_id":"v141-c-R010-C002","kind":"mathematical","role":"core","statement":"Electricity fed into the day-ahead market receives compensation at the dynamic wholesale spot price. Scope: Community electricity infeed into the wholesale day-ahead market. Condition: Electricity is fed into the day-ahead market.","expression":"-\\sum_{h \\in H}\\sum_{t \\in T} p_{F}^{(t)} F_{DA}^{(t,h)}","formalization_origin":"source","template_id":null,"members":["settlement.payment","execution.energy_trade"],"variable_refs":["v141-c-R010-x002"],"parameter_refs":["v141-c-R010-p002"],"evidence_ids":["v141-b-g01-e09","v141-b-g02-e30","v141-b-g02-e31","v141-b-g02-e36"]},{"constraint_id":"v141-c-R010-C003","kind":"mathematical","role":"supporting","statement":"The day-ahead payment objective component is the sum over houses and time steps of day-ahead grid consumption valued at the dynamic day-ahead price minus day-ahead feed compensated at the dynamic feed-in price, corresponding to the right-hand side of Eq. (15).","expression":"\\sum_{h \\in H}\\sum_{t \\in T} \\left( p_{G\\_DA}^{(t)} G_{DA}^{(t,h)} - p_{F}^{(t)} F_{DA}^{(t,h)} \\right)","formalization_origin":"source","template_id":null,"members":["settlement.payment","execution.energy_trade"],"variable_refs":["v141-c-R010-x001","v141-c-R010-x002"],"parameter_refs":["v141-c-R010-p001","v141-c-R010-p002"],"evidence_ids":["v141-b-g02-e30","v141-b-g02-e31"]},{"constraint_id":"v141-c-R010-C004","kind":"mathematical","role":"supporting","statement":"The expected intraday payment objective component is the scenario-probability-weighted sum over time steps, houses, and scenarios of intraday grid consumption valued at the uncertain intraday spot price, corresponding to the right-hand side of Eq. (16).","expression":"\\sum_{t \\in T}\\sum_{h \\in H}\\sum_{s \\in S} \\pi^{(s)} p_{G\\_ID}^{(t,s)} G_{ID}^{(t,h,s)}","formalization_origin":"source","template_id":null,"members":["settlement.payment","execution.energy_trade"],"variable_refs":["v141-c-R010-x003"],"parameter_refs":["v141-c-R010-p003","v141-c-R010-p004"],"evidence_ids":["v141-b-g02-e21","v141-b-g02-e32"]}],"pi":[{"evidence_id":"v141-b-g01-e09","location":{"location_id":"src-3c39fd6f72-p05-c1r2__v141-a-M01-pricing","page":5,"printed_page":null,"section":null,"anchor_text":"Fig. 2. Flow diagram fo the local market are lower than the grid consumption price (i.e. • the price","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-05.png","occurrence_role":"condition"},"source_text":"To incentivise local P2P trade at all times, we assume that the trade prices within the local market are lower than the grid consumption price (i.e. the price in the wholesale electricity market including, among others, grid fees; more details on prices in Section 4.3). For electricity fed into the grid, prosumers receive the dynamic wholesale spot price as compensation which is lower than the dynamic local P2P price. The source of electricity for infeed can only be DG or the residential battery, but to promote the local utilisation of distributed energy resources, local markets should consider a price structure with \\(p_F^{(t)} \\le p_{P2P}^{(t)} \\le p_{DA\\_G}^{(t)}\\), i.e. feed price ≤ P2P price ≤ grid price."},{"evidence_id":"v141-b-g02-e30","location":{"location_id":"src-3c39fd6f72-p07-c1r4__v141-a-M01-pricing","page":7,"printed_page":null,"section":null,"anchor_text":"y y p grid at dynamic real-time prices and compensations are paid when 4.2 electricity is fed into t","equation_id":"Eqs. (14)-(15)","figure_id":null,"table_id":null,"image_ref":"pages/page-07.png","occurrence_role":"formula"},"source_text":"The objective of the model is to minimise costs of electricity for the community. Costs arise when electricity is procured from the grid at dynamic real-time prices and compensations are paid when electricity is fed into the day-ahead market. The two-stage model incorporates two market stages that add stage-specific components to the overall objective function. That is, the objective function is split into the day-ahead (O_{DA}) and intraday market (O_{ID}) objectives, see Eq. (14). min {O_{DA} + O_{ID}} \\qquad (14)"},{"evidence_id":"v141-b-g02-e21","location":{"location_id":"src-3c39fd6f72-p06-c1r1__v141-a-M01-clearing","page":6,"printed_page":null,"section":null,"anchor_text":"J.M. Zepter, A. Lüth and P. Crespo del Granado et Table 1 Designated sets, parameters and variables ","equation_id":null,"figure_id":null,"table_id":"Table 1","image_ref":"pages/page-06.png","occurrence_role":"definition"},"source_text":"Table 1 Designated sets, parameters and variables of the mathematical model. Sets: t ∈ T hours t in time horizon T; h, p ∈ H houses h and peers p in community H; s ∈ S scenarios s in set of scenarios S. Scalars: \\psi^{P2P} efficiency factor for conversion and transmission of DG sources to P2P sale; \\underline{s}/\\overline{s} upper/lower bounds of storage level in battery; α/β maximum charging/discharging rate of battery; η^{c}/η^{d} battery charging/discharging efficiency. Parameters: dem^{(t,h)} demand of house h in time step t; res^{(t,h)} renewable energy production of house h in time step t; \\widetilde{res}^{(t,h,s)} renewable energy production of house h in time step t and scenario s; δ^{(t,h,s)} deviations in production of house h in time step t and scenario s; π_{s} probability of occurrence of renewable scenario s; p_{DA}^{(t)} price of electricity from the grid in the day-ahead market in time step t; p_{ID}^{(t,s)} price of electricity from the grid in the intraday market in time step t and scenario s; p_{F}^{(t)} price of electricity fed into the grid in time step t; p_{P2P}^{(t)} price of electricity in the local market in time step t. Variables: C_{DA}^{(t,h)} day-ahead charge of battery of house h in time step t; C_{ID}^{(t,h,s)} intraday charge of battery of house h in time step t and scenario s; D_{DA}^{(t,h)} day-ahead discharge of battery of house h in time step t; D_{ID}^{(t,h,s)} intraday discharge of battery of house h in time step t and scenario s; F_{DA}^{(t,h)} day-ahead feed of house h in time step t; G_{DA}^{(t,h)} day-ahead grid consumption of house h in time step t; G_{ID}^{(t,h,s)} intraday grid consumption of house h in time step t and scenario s; I_{DA}^{(t,h)} day-ahead P2P electricity purchase of house h in time step t; I_{ID}^{(t,h,s)} intraday P2P electricity purchase of house h in time step t and scenario s; I_{p,ID}^{(t,h←p,s)} intraday P2P electricity purchase of house h from peer p in time step t and scenario s; P^{(t,h)} day-ahead planned electricity supply of house h in time step t; Q^{(t,h)} day-ahead demanded electricity quantity of house h in time step t; S^{(t,h,s)} energy storage level in battery of house h in time step t and scenario s; X_{DA}^{(t,h)} day-ahead P2P electricity sale of house h in time step t; X_{ID}^{(t,h,s)} intraday P2P electricity sale of house h in time step t and scenario s; X_{p,ID}^{(t,h→p,s)} intraday P2P electricity sale of house h from peer p in time step t and scenario s."},{"evidence_id":"v141-b-g02-e31","location":{"location_id":"src-3c39fd6f72-p07-c1r4__v141-a-M01-pricing","page":7,"printed_page":null,"section":null,"anchor_text":"y y p grid at dynamic real-time prices and compensations are paid when 4.2 electricity is fed into t","equation_id":"Eqs. (14)-(15)","figure_id":null,"table_id":null,"image_ref":"pages/page-07.png","occurrence_role":"formula"},"source_text":"The day-ahead objective, Eq. (15), comprises the day-ahead planned grid consumption G_{DA}^{(t,h)} at the dynamic price p_{G\\_DA}^{(t)} and the day-ahead feed-in F_{DA}^{(t,h)} at a dynamic compensation p_{F}^{(t)}. Costs for P2P trade do not arise at community level as the P2P purchase of one peer is at the same time the sale of another. O_{DA} = \\sum_{h,t} [p_{G\\_DA}^{(t)} · G_{DA}^{(t,h)} − p_{F}^{(t)} · F_{DA}^{(t,h)}] \\qquad (15)"},{"evidence_id":"v141-b-g02-e32","location":{"location_id":"src-3c39fd6f72-p07-c2r1__v141-a-M01-pricing","page":7,"printed_page":null,"section":null,"anchor_text":"ado et al. / Energy & Buildings 184 (2019) 163–176 . In the intraday market, costs arise when electr","equation_id":"Eq. (16)","figure_id":null,"table_id":null,"image_ref":"pages/page-07.png","occurrence_role":"formula"},"source_text":"In the intraday market, costs arise when electricity is procured from the wholesale intraday market G_{ID}^{(t,h,s)} at an uncertain intraday spot price p_{G\\_ID}^{(t,s)}. The intraday market’s expected objective value is obtained from the sum over the scenarios while taking into account their respective probabilities. O_{ID} = \\sum_{t,h,s} π^{(s)} [p_{G\\_ID}^{(t,s)} · G_{ID}^{(t,h,s)}] \\qquad (16)"},{"evidence_id":"v141-b-g02-e36","location":{"location_id":"src-3c39fd6f72-p09-c1r1__v141-a-M01-pricing","page":9,"printed_page":null,"section":null,"anchor_text":"170 J.M. Zepter, A. Lüth and P. Crespo del Granado et al. / (2) Intraday price scenarios: Exact intr","equation_id":null,"figure_id":null,"table_id":null,"image_ref":"pages/page-09.png","occurrence_role":"definition"},"source_text":"(3) Feed-in prices: Most of today’s feed-in tariffs are static subsidies that are paid by the energy supplier for the infeed based on metered data. Depending on the eligibility, prosumers in UK’s market receive for their small-scale installation (\u003c 10 kW) between 0.31 – 4.01 pence/kWh for PV and 8.46 pence/kWh for wind power. Our approach for this pricing scheme is to set them equal to the RPD prices, i.e. the wholesale spot market prices. In contrast to the flat tariff structure today, these prices incentivise the participation in the day-ahead market differently throughout the course of a day."}],"field_notes":{"empty_E_reason":null,"empty_x_reason":null,"empty_theta_reason":null},"evidence_basis":"explicit","implementation_status":"unimplemented","status":"needs_review","lead_ids":["v141-a-M01-clearing","v141-a-M01-coordination","v141-a-M01-pricing"],"extras":{"decision_anchor":"settlement.payment","graph_fact_supports":[[{"evidence_id":"v141-b-g02-e30","quote":"Costs arise when electricity is procured from the grid at dynamic real-time prices"}],[{"evidence_id":"v141-b-g02-e30","quote":"compensations are paid when electricity is fed into the day-ahead market."},{"evidence_id":"v141-b-g01-e09","quote":"For electricity fed into the grid, prosumers receive the dynamic wholesale spot price as compensation"}]],"C2_formalization":{"graph_sha256":"4628e46f9f9f3a4768e5661fd4b6e631048ce7b96e16566e839cb3fa5291f388","applicability":"formalized","reason":"The frozen rule is a settlement/payment rule. The supplied source gives objective equations (14)-(16): day-ahead grid consumption is charged at the dynamic day-ahead grid price, day-ahead feed earns a dynamic feed-in compensation, and intraday grid consumption is charged at an uncertain intraday spot price weighted by scenario probabilities. Existing constraints C001 and C002 are formalized as the grid-procurement cost component and the day-ahead feed-compensation component; C003 and C004 add the exact right-hand-side payment components of Eqs. (15) and (16). B evidence is unreviewed in this experiment; no source-audit claim is made.","bindings":[{"object_id":"v141-c-R010-x001","node_ids":["execution.energy_trade","settlement.payment"],"edge_ids":["v141-c-R010-E001"],"rationale":"G_DA is the day-ahead grid-consumption quantity in Eq. (15); its procurement is the traded energy to which settlement.payment is conditionally attached on the frozen edge E001."},{"object_id":"v141-c-R010-x002","node_ids":["execution.energy_trade","settlement.payment"],"edge_ids":["v141-c-R010-E001"],"rationale":"F_DA is the day-ahead feed quantity in Eq. (15); the source records its compensation as a negative cost term in the payment objective, linked through the frozen conditional-on edge E001."},{"object_id":"v141-c-R010-x003","node_ids":["execution.energy_trade","settlement.payment"],"edge_ids":["v141-c-R010-E001"],"rationale":"G_ID is the intraday grid-consumption quantity in Eq. (16); it supports the second-stage procurement cost in the same settlement.payment relation and is linked through E001."},{"object_id":"v141-c-R010-p001","node_ids":["settlement.payment"],"edge_ids":[],"rationale":"p_G_DA is a price parameter in the settlement/payment cost formula, not a traded quantity; it is bound directly to settlement.payment."},{"object_id":"v141-c-R010-p002","node_ids":["settlement.payment"],"edge_ids":[],"rationale":"p_F is the feed-in compensation price parameter in the settlement/payment formula, not a traded quantity; it is bound directly to settlement.payment."},{"object_id":"v141-c-R010-p003","node_ids":["settlement.payment"],"edge_ids":[],"rationale":"p_G_ID is the uncertain intraday price parameter used to value second-stage grid procurement in the payment formula; it is bound directly to settlement.payment."},{"object_id":"v141-c-R010-p004","node_ids":["settlement.payment"],"edge_ids":[],"rationale":"pi is the scenario-probability weight used in the expected intraday payment expression; it is bound directly to settlement.payment."},{"object_id":"v141-c-R010-C001","node_ids":["settlement.payment","execution.energy_trade"],"edge_ids":["v141-c-R010-E001"],"rationale":"C001 formalizes the positive grid-procurement cost terms of Eqs. (15)-(16) for the two-stage scope; the frozen conditional-on edge E001 records that payment depends on the energy trade."},{"object_id":"v141-c-R010-C002","node_ids":["settlement.payment","execution.energy_trade"],"edge_ids":["v141-c-R010-E001"],"rationale":"C002 formalizes the negative p_F F_DA compensation term from Eq. (15); the frozen conditional-on edge E001 records payment conditional on day-ahead feed."},{"object_id":"v141-c-R010-C003","node_ids":["settlement.payment","execution.energy_trade"],"edge_ids":["v141-c-R010-E001"],"rationale":"C003 is the right-hand side of Eq. (15), combining the day-ahead procurement cost and feed-in compensation. It is a supporting formalization of the payment relation over execution.energy_trade."},{"object_id":"v141-c-R010-C004","node_ids":["settlement.payment","execution.energy_trade"],"edge_ids":["v141-c-R010-E001"],"rationale":"C004 is the right-hand side of Eq. (16), giving expected intraday procurement cost. It is a supporting formalization of the payment relation over execution.energy_trade."}],"revision_requests":["B evidence remains unreviewed in this experiment; the formalization and all evidence attachments are provisional pending independent source audit.","Notation normalization is needed: Eq. (15) uses p_{G\\_DA}^{(t)} and Eq. (16) uses p_{G\\_ID}^{(t,s)}, while Table 1 uses p_{DA}^{(t)} and p_{ID}^{(t,s)}. This patch preserves the equation notation and does not assert more than the source's day-ahead/intraday grid-price meaning.","B re-extraction should confirm units, sign restrictions, and domains for G_{DA}, G_{ID}, and F_{DA}; the supplied equations do not state bounds or units for these quantities."]}},"quarantined_references":[]}});
